// Code generated by AI (Claude Sonnet 5)

'use strict'

const assert = require('node:assert/strict')
const { spawnSync } = require('node:child_process')
const fs = require('node:fs')
const os = require('node:os')
const path = require('node:path')
const { after, before, describe, test } = require('node:test')

const CONFIG = {
    allowlist: ['~/.claude/CLAUDE.md'],
    denylist: ['**/.env', '**/.git/config', '**/.git/hooks', '~/.agents', '~/.apm', '~/.aws', '~/.claude', '~/.codex', '~/.config', '~/.copilot', '~/.ssh'],
}

const HOOK = path.join(__dirname, '..', 'scripts', 'protected-paths.js')

// SHAPES builds the same shell call as each runtime sends it.
const SHAPES = {
    claude: (command, cwd) => ({ cwd, tool_input: { command } }),
    codex: (command, cwd) => ({ cwd, tool_input: { command }, tool_name: 'Bash' }),
    copilot: (command, cwd) => ({ cwd, toolArgs: { command }, toolName: 'bash' }),
    'copilot with encoded arguments': (command, cwd) => ({ cwd, toolArgs: JSON.stringify({ command }), toolName: 'bash' }),
    cursor: (command, cwd) => ({ cwd, tool_input: { command }, tool_name: 'Shell' }),
}

const assertDenied = (output, reason) => {
    assert.ok(output, 'expected the call to be denied')
    assert.equal(output.hookSpecificOutput.permissionDecision, 'deny')
    assert.ok(output.reason.includes(reason), `expected '${output.reason}' to include '${reason}'`)
}

// shell builds a Claude Code shell call, where `$PROJECT` and `$HOME` stand for the directories of the test.
const shell = (command, cwd = '$PROJECT') => SHAPES.claude(command, cwd)

describe('protected-paths', () => {
    let root
    let project
    const homes = new Map()

    before(() => {
        root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'protected-paths-')))
        project = path.join(root, 'project')
        fs.mkdirSync(path.join(project, '.git', 'hooks'), { recursive: true })
        fs.mkdirSync(path.join(project, 'link'))
        fs.mkdirSync(path.join(project, 'sub'))
        fs.writeFileSync(path.join(project, '.env'), 'x')
        fs.writeFileSync(path.join(project, '.git', 'hooks', 'pre-commit'), 'x')
        fs.writeFileSync(path.join(project, 'README.md'), 'x')
        fs.writeFileSync(path.join(project, 'secret'), 'x')
        fs.symlinkSync(path.join(project, 'secret'), path.join(project, 'link', '.env'))
    })

    after(() => fs.rmSync(root, { force: true, recursive: true }))

    // homeFor creates a home holding config.json (an object is serialized, a string is written verbatim, null writes nothing).
    const homeFor = (config) => {
        const key = JSON.stringify(config)
        if (!homes.has(key)) {
            const home = fs.mkdtempSync(path.join(root, 'home-'))
            if (config !== null) {
                fs.mkdirSync(path.join(home, '.config', 'protected-paths'), { recursive: true })
                fs.writeFileSync(path.join(home, '.config', 'protected-paths', 'config.json'), typeof config === 'string' ? config : JSON.stringify(config))
            }
            homes.set(key, home)
        }
        return homes.get(key)
    }

    // run sends a payload (or raw stdin) to the hook and returns the parsed deny output, or null when the call is allowed.
    // `$HOME` and `$PROJECT` in a payload stand for the home and the project of the test.
    const run = (payload, { config = CONFIG, raw } = {}) => {
        const home = homeFor(config)
        const input = raw ?? JSON.stringify(payload).replaceAll('$HOME', home).replaceAll('$PROJECT', project)

        const { status, stdout } = spawnSync(process.execPath, [HOOK], { encoding: 'utf8', env: { ...process.env, HOME: home }, input })

        assert.equal(status, 0)
        return stdout === '' ? null : JSON.parse(stdout)
    }

    describe('config and payload', () => {
        test('no config file allows every call', () => {
            // Act
            const output = run(shell('cat ~/.ssh/id_rsa'), { config: null })

            // Assert
            assert.equal(output, null)
        })

        test('a malformed config.json denies every call', () => {
            // Act
            const output = run(shell('echo hello'), { config: 'not json' })

            // Assert
            assertDenied(output, 'config.json is not valid JSON')
        })

        test('a malformed payload is denied', () => {
            // Act
            const output = run(null, { raw: 'not json' })

            // Assert
            assertDenied(output, 'payload is not valid JSON')
        })

        test('unparsable tool arguments are denied', () => {
            // Act
            const output = run({ toolArgs: 'not json', toolName: 'bash' })

            // Assert
            assertDenied(output, 'tool arguments is not valid JSON')
        })
    })

    describe('denylist and allowlist', () => {
        const denied = [
            ['~/.agents/state.json', '.agents'],
            ['~/.apm/credentials.json', '.apm'],
            ['~/.aws/credentials', '.aws'],
            ['~/.claude/.credentials.json', '.claude'],
            ['~/.claude/config.json', '.claude'],
            ['~/.codex/auth.json', '.codex'],
            ['~/.config/some-other-app/secrets.json', '.config'],
            ['~/.copilot/config.json', '.copilot'],
            ['~/.ssh/id_rsa', '.ssh'],
        ]
        for (const [target, entry] of denied) {
            test(`denies cat ${target}`, () => {
                // Act
                const output = run(shell(`cat ${target}`))

                // Assert
                assertDenied(output, entry)
            })
        }

        const ancestors = [
            ['grep -r password ~'],
            ['find $HOME -name id_rsa'],
            ['cd ~'],
        ]
        for (const [command] of ancestors) {
            test(`denies ${command} as an ancestor of a protected path`, () => {
                // Act
                const output = run(shell(command))

                // Assert
                assertDenied(output, 'ancestor of protected path')
            })
        }

        test('allows a command that references nothing protected', () => {
            // Act
            const output = run(shell('echo hello-world'))

            // Assert
            assert.equal(output, null)
        })

        test('ignores transcript_path, which is bookkeeping and not a tool argument', () => {
            // Act
            const output = run({ cwd: '$PROJECT', tool_input: { command: 'echo hi' }, transcript_path: '~/.claude/projects/foo/session.jsonl' })

            // Assert
            assert.equal(output, null)
        })

        test('denies a command run inside a protected directory, even without a path argument', () => {
            // Act
            const output = run({ cwd: '$HOME/.ssh', tool_input: { command: '' } })

            // Assert
            assertDenied(output, '.ssh')
        })

        test('normalizes a trailing slash and a $HOME prefix in an entry', () => {
            // Arrange
            const config = { denylist: ['~/.ssh/', '$HOME/.aws'] }

            // Act
            const ssh = run(shell('cat ~/.ssh/id_rsa'), { config })
            const aws = run(shell('cat ~/.aws/credentials'), { config })

            // Assert
            assertDenied(ssh, '.ssh')
            assertDenied(aws, '.aws')
        })

        test('lets * and ? work in an absolute entry, ancestors included', () => {
            // Arrange
            const config = { denylist: ['~/.config/*/secrets'] }

            // Act
            const secrets = run(shell('cat ~/.config/gh/secrets'), { config })
            const other = run(shell('cat ~/.config/gh/hosts'), { config })
            const ancestor = run(shell('grep -r token ~/.config/gh'), { config })

            // Assert
            assertDenied(secrets, '.config/*/secrets')
            assert.equal(other, null)
            assertDenied(ancestor, 'ancestor of protected path')
        })

        test('lets an allowlist entry lift a denylist match', () => {
            // Act
            const output = run(shell('cat ~/.claude/CLAUDE.md'))

            // Assert
            assert.equal(output, null)
        })

        test('denies an allowed path chained with a denied one', () => {
            // Act
            const output = run(shell('cat ~/.claude/CLAUDE.md; cat ~/.ssh/id_rsa'))

            // Assert
            assertDenied(output, '.ssh')
        })

        test('resolves a ".." segment to its real destination', () => {
            // Act
            const output = run(shell('cat ~/.claude/CLAUDE.md/../../.ssh/id_rsa'))

            // Assert
            assertDenied(output, '.ssh')
        })
    })

    describe('runtime payloads', () => {
        for (const [runtime, shape] of Object.entries(SHAPES)) {
            test(`${runtime}: denies a protected path`, () => {
                // Act
                const output = run(shape('cat ~/.ssh/id_rsa', '$PROJECT'))

                // Assert
                assertDenied(output, '.ssh')
            })

            test(`${runtime}: denies a command run inside a protected directory`, () => {
                // Act
                const output = run(shape('ls -la', '$HOME/.ssh'))

                // Assert
                assertDenied(output, '.ssh')
            })

            test(`${runtime}: allows a command run in the home directory`, () => {
                // Act
                const output = run(shape('curl https://example.com', '$HOME'))

                // Assert
                assert.equal(output, null)
            })
        }

        test('writes the deny format of every runtime', () => {
            // Act
            const output = run(SHAPES.cursor('cat ~/.ssh/id_rsa', '$PROJECT'))

            // Assert
            assert.equal(output.permission, 'deny')
            assert.equal(output.permissionDecision, 'deny')
            assert.equal(output.decision, 'block')
        })
    })

    describe('tool fields', () => {
        const fields = [
            [{ file_path: '~/.ssh/id_rsa' }],
            [{ absolute_path: '$HOME/.ssh/id_rsa' }],
            [{ glob: '~/.ssh/*', path: '.', pattern: 'password' }],
        ]
        for (const [toolInput] of fields) {
            test(`denies ${JSON.stringify(toolInput)}`, () => {
                // Act
                const output = run({ cwd: '$PROJECT', tool_input: toolInput })

                // Assert
                assertDenied(output, '.ssh')
            })
        }

        test('resolves glob and pattern against the path field', () => {
            // Act
            const denied = run({ cwd: '$PROJECT', tool_input: { glob: 'hooks/pre-commit', path: '.git' } })
            const allowed = run({ cwd: '$PROJECT', tool_input: { glob: 'hooks/pre-commit' } })

            // Assert
            assertDenied(denied, '**/.git/hooks')
            assert.equal(allowed, null)
        })

        test('resolves a relative file_path against the cwd', () => {
            // Act
            const output = run({ cwd: '$HOME/project', tool_input: { file_path: '../.ssh/id_rsa' } })

            // Assert
            assertDenied(output, '.ssh')
        })

        test('resolves a relative command reference against the cwd', () => {
            // Act
            const denyOutput = run(shell('cat ../.ssh/id_rsa', '$HOME/project'))
            const allowOutput = run(shell('cat ../notes.txt', '$HOME/project'))

            // Assert
            assertDenied(denyOutput, '.ssh')
            assert.equal(allowOutput, null)
        })
    })

    describe('entries starting with **/', () => {
        const denied = [
            ['echo x > .git/hooks/pre-commit', '**/.git/hooks'],
            ['cat /work/other/.git/config', '**/.git/config'],
            ['cd ../other && cat .git/hooks/pre-commit', '**/.git/hooks'],
            ['cat ~/.local/x/.env', '**/.env'],
        ]
        for (const [command, entry] of denied) {
            test(`denies ${command}`, () => {
                // Act
                const output = run(shell(command, '/work/repo'))

                // Assert
                assertDenied(output, entry)
            })
        }

        test('does not deny git commands or the .git directory itself', () => {
            // Arrange
            const commands = ['git -C /work/repo status', 'ls /work/repo/.git', 'cat /work/repo/.git/HEAD', 'cat .git/config.bak', 'cat .github/hooks.json']

            // Act and Assert
            for (const command of commands) {
                assert.equal(run(shell(command, '/work/repo')), null, command)
            }
        })

        test('denies a symlink named like a protected file, but not its target', () => {
            // Act
            const link = run(shell('cat link/.env'))
            const target = run(shell('cat secret'))

            // Assert
            assertDenied(link, '**/.env')
            assert.equal(target, null)
        })
    })

    describe('an allowlist entry starting with **/', () => {
        // Protects any `.git` directory, except its `info` subdirectory.
        const config = { allowlist: ['**/.git/info'], denylist: ['**/.git'] }

        test('lifts a denylist entry starting with **/', () => {
            // Act
            const allowed = run(shell('cat .git/info/exclude', '/work/repo'), { config })
            const denied = run(shell('cat .git/HEAD', '/work/repo'), { config })

            // Assert
            assert.equal(allowed, null)
            assertDenied(denied, '**/.git')
        })
    })

    describe('* and ? inside an entry component', () => {
        const config = {
            allowlist: [],
            denylist: ['**/*.jks', '**/.claude/settings*.json', '**/.env', '**/.env.*.local', '**/a?c', '**/f+(1).txt', '**/x.y'],
        }

        test('names the matching entry in the deny reason', () => {
            // Act
            const output = run({ cwd: '/work/repo', tool_input: { file_path: '/work/repo/.claude/settings.local.json' } }, { config })

            // Assert
            assertDenied(output, '**/.claude/settings*.json')
        })

        const globs = [
            [{ command: 'cat a/b/app.jks' }, true],
            [{ command: 'cat app.jks.txt' }, false],
            [{ command: 'cat jks' }, false],
            [{ command: 'cat app.jks/inside' }, true],
            [{ command: 'cat x/abc' }, true],
            [{ command: 'cat x/ac' }, false],
            [{ command: 'cat a/c' }, false],
            [{ command: 'cat .env.prod.local' }, true],
            [{ command: 'cat .env.local' }, false],
            [{ command: 'cat .env.prod' }, false],
            [{ file_path: '/work/repo/x.y' }, true],
            [{ file_path: '/work/repo/xzy' }, false],
            [{ file_path: '/work/repo/f+(1).txt' }, true],
            [{ file_path: '/work/repo/ff1.txt' }, false],
            [{ command: 'docker run --env-file=.env alpine env' }, true],
            [{ command: 'git show HEAD:.env' }, true],
            [{ command: 'git show HEAD:README.md' }, false],
        ]
        for (const [toolInput, isDenied] of globs) {
            test(`${isDenied ? 'denies' : 'allows'} ${JSON.stringify(toolInput)}`, () => {
                // Act
                const output = run({ cwd: '/work/repo', tool_input: toolInput }, { config })

                // Assert
                assert.equal(output !== null, isDenied)
            })
        }
    })

    describe('directory changes', () => {
        const denied = [
            'cd .git && cat hooks/pre-commit',
            'cd -P .git && cat hooks/pre-commit',
            'cd sub && cd ../.git && cat hooks/pre-commit',
            'pushd .git; cat hooks/pre-commit',
            'chdir .git; cat hooks/pre-commit',
            'builtin cd .git && cat hooks/pre-commit',
            'tar -C .git -cf - hooks/pre-commit',
            'tar --directory=.git -cf - hooks/pre-commit',
            'env --chdir=.git cat hooks/pre-commit',
        ]
        for (const command of denied) {
            test(`denies ${command}`, () => {
                // Act
                const output = run(shell(command))

                // Assert
                assertDenied(output, '**/.git/hooks')
            })
        }

        test('allows a relative path after a cd that reaches nothing protected', () => {
            // Act
            const output = run(shell('cd sub && git add .'))

            // Assert
            assert.equal(output, null)
        })
    })

    describe('shell globs', () => {
        const denied = ['cat .env*', 'cat [.]env', 'cat .e?v', 'cd sub && cat ../.env*']
        for (const command of denied) {
            test(`denies ${command}`, () => {
                // Act
                const output = run(shell(command))

                // Assert
                assertDenied(output, '**/.env')
            })
        }

        test('allows a glob that matches nothing protected', () => {
            // Act
            const output = run(shell('cat *.md'))

            // Assert
            assert.equal(output, null)
        })
    })
})
